INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('enerji','Enerji ve Tabii Kaynaklar', '[{"ad":"Güneş ve rüzgâr yatırımı","aciklama":"Seçilen ilde yenilenebilir enerji sahası kurulur; ilin gelişmişliği artar.","maliyet":6,"il_gerekli":true,"etki":{"gelisim":2,"buyume":0.03},"oyuncu":[]},{"ad":"Enerji faturası destek programı","aciklama":"Ülke genelinde oyuncuların geçim gideri 7 gün %4 azalır.","maliyet":5,"il_gerekli":false,"etki":{"memnuniyet":0.3},"oyuncu":[{"tur":"gecim","deger":4}]},{"ad":"Elektrik şebekesi modernizasyonu","aciklama":"Seçilen ilin şebeke altyapısı iyileştirilir.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.5},"oyuncu":[]},{"ad":"Enerji verimliliği teşviki","aciklama":"Verimli üretime destek ülke büyümesini artırır.","maliyet":3,"il_gerekli":false,"etki":{"buyume":0.06},"oyuncu":[]}]'::jsonb,'[{"ad":"Yenilenebilir enerji forumu","aciklama":"Oyuncular enerji yatırımlarını tartışır.","il_gerekli":false,"etki":{"memnuniyet":0.2},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Yerel enerji çalıştayı","aciklama":"İl enerji sorunları ve tasarruf çözümleri görüşülür.","il_gerekli":true,"etki":{"gelisim":0.3,"il_memnuniyet":0.6},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('cevre','Çevre, Şehircilik ve İklim', '[{"ad":"Kentsel dönüşüm projeleri","aciklama":"Seçilen ilde şehircilik hizmetleri gelişir.","maliyet":6,"il_gerekli":true,"etki":{"gelisim":2},"oyuncu":[]},{"ad":"Atık dönüşüm altyapısı","aciklama":"Seçilen ilde geri dönüşüm altyapısı kurulur.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.2,"memnuniyet":0.1},"oyuncu":[]},{"ad":"İklim uyum yatırımı","aciklama":"Ülke çapında iklim uyum hizmetleri genişler.","maliyet":5,"il_gerekli":false,"etki":{"memnuniyet":0.25},"oyuncu":[]},{"ad":"Yeşil yapı teşviki","aciklama":"Verimli binalara destek ekonomik büyümeye katkı sağlar.","maliyet":4,"il_gerekli":false,"etki":{"buyume":0.05},"oyuncu":[]}]'::jsonb,'[{"ad":"İklim ve şehir forumu","aciklama":"Halkın kent ve çevre önerileri dinlenir.","il_gerekli":false,"etki":{"memnuniyet":0.25},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Temiz çevre günü","aciklama":"Seçilen ilde gönüllüler çevre çalışmasına katılır.","il_gerekli":true,"etki":{"il_memnuniyet":0.8,"gelisim":0.4},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('kultur','Kültür ve Turizm', '[{"ad":"Kültür merkezi inşası","aciklama":"Seçilen ilde kültür merkezi hizmete girer.","maliyet":5,"il_gerekli":true,"etki":{"gelisim":2},"oyuncu":[]},{"ad":"Tarihi miras restorasyonu","aciklama":"Seçilen ilde kültürel eserlerin erişilebilirliği artar.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.5,"memnuniyet":0.15},"oyuncu":[]},{"ad":"Turizm tanıtım kampanyası","aciklama":"Turizm alanında ekonomik hareketlilik büyümeyi artırır.","maliyet":4,"il_gerekli":false,"etki":{"buyume":0.07},"oyuncu":[]},{"ad":"Sanat eğitim bursları","aciklama":"Oyuncuların kıdem kazanımı 7 gün %10 artar.","maliyet":3,"il_gerekli":false,"etki":{"memnuniyet":0.2},"oyuncu":[{"tur":"kidem_x","deger":10}]}]'::jsonb,'[{"ad":"Kültür ve sanat festivali","aciklama":"Gerçek oyuncular kültür etkinliğine katılır.","il_gerekli":true,"etki":{"il_memnuniyet":1,"gelisim":0.5},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Turizm çalıştayı","aciklama":"Turizm projeleri ve tanıtım politikaları konuşulur.","il_gerekli":false,"etki":{"buyume":0.02,"memnuniyet":0.15},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('dijital','Dijital Dönüşüm ve Siber Güvenlik', '[{"ad":"E-devlet dönüşüm programı","aciklama":"Kamu işlemleri dijitalleşir; ülke memnuniyeti artar.","maliyet":4,"il_gerekli":false,"etki":{"memnuniyet":0.4},"oyuncu":[]},{"ad":"Geniş bant altyapı desteği","aciklama":"Seçilen ilin dijital altyapısı güçlenir.","maliyet":5,"il_gerekli":true,"etki":{"gelisim":2},"oyuncu":[]},{"ad":"Siber güvenlik eğitimi","aciklama":"Oyuncuların kıdem kazanımı 7 gün %12 artar.","maliyet":3,"il_gerekli":false,"etki":{"memnuniyet":0.2},"oyuncu":[{"tur":"kidem_x","deger":12}]},{"ad":"Akıllı şehir uygulaması","aciklama":"Seçilen ilde akıllı şehir yatırımı yapılır.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.5},"oyuncu":[]}]'::jsonb,'[{"ad":"Dijital hizmetler forumu","aciklama":"Çevrim içi hizmet önerileri toplanır.","il_gerekli":false,"etki":{"memnuniyet":0.25},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Siber farkındalık buluşması","aciklama":"İlde oyuncular dijital güvenlik deneyimlerini paylaşır.","il_gerekli":true,"etki":{"il_memnuniyet":0.8},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('aile','Aile ve Sosyal Hizmetler', '[{"ad":"Kreş ve aile merkezi","aciklama":"Seçilen ilde kreş ve aile hizmeti kurulur.","maliyet":5,"il_gerekli":true,"etki":{"gelisim":1.8,"memnuniyet":0.2},"oyuncu":[]},{"ad":"Engelsiz yaşam merkezleri","aciklama":"Seçilen ilde erişilebilir kamu hizmetleri geliştirilir.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.5},"oyuncu":[]},{"ad":"Aile yaşam gideri desteği","aciklama":"Oyuncuların geçim yükü 7 gün %5 azalır.","maliyet":6,"il_gerekli":false,"etki":{"memnuniyet":0.35},"oyuncu":[{"tur":"gecim","deger":5}]},{"ad":"Yaşlı ve bakım hizmeti","aciklama":"Ülke çapında bakım ve sosyal hizmet desteği sağlanır.","maliyet":4,"il_gerekli":false,"etki":{"memnuniyet":0.35},"oyuncu":[]}]'::jsonb,'[{"ad":"Aile ve çocuk çalıştayı","aciklama":"Ailelerin sosyal hizmet önerileri alınır.","il_gerekli":false,"etki":{"memnuniyet":0.3},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Engelsiz yaşam buluşması","aciklama":"Seçilen ilde kapsayıcı katılım etkinliği yapılır.","il_gerekli":true,"etki":{"il_memnuniyet":1},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('genclik','Gençlik ve Spor', '[{"ad":"Spor tesisi inşa programı","aciklama":"Seçilen ile yeni spor altyapısı kurulur.","maliyet":5,"il_gerekli":true,"etki":{"gelisim":1.7},"oyuncu":[]},{"ad":"Gençlik merkezi açılışı","aciklama":"Seçilen ilde gençlik etkinlikleri için merkez açılır.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.4,"memnuniyet":0.1},"oyuncu":[]},{"ad":"Burs ve beceri destekleri","aciklama":"Oyuncuların 7 gün kıdem kazanımı %15 artar.","maliyet":4,"il_gerekli":false,"etki":{"memnuniyet":0.2},"oyuncu":[{"tur":"kidem_x","deger":15}]},{"ad":"Genç istihdam teşviki","aciklama":"Yeni oyuncuların ücretleri 7 gün %8 artar.","maliyet":5,"il_gerekli":false,"etki":{"issizlik":-0.05},"oyuncu":[{"tur":"ucret_yeni","deger":8}]}]'::jsonb,'[{"ad":"Gençlik ve spor festivali","aciklama":"Genç oyuncuların katıldığı spor buluşması.","il_gerekli":true,"etki":{"il_memnuniyet":0.8,"gelisim":0.3},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Kariyer ve spor konferansı","aciklama":"Ülke genelinden oyuncular deneyim paylaşır.","il_gerekli":false,"etki":{"memnuniyet":0.25},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('afet','Afet ve Acil Durum', '[{"ad":"Afet toplanma alanı altyapısı","aciklama":"Seçilen ilde afet toplanma alanları geliştirilir.","maliyet":5,"il_gerekli":true,"etki":{"gelisim":2},"oyuncu":[]},{"ad":"Erken uyarı sistemi kurulumu","aciklama":"Seçilen ilin haberleşme altyapısı güçlendirilir.","maliyet":5,"il_gerekli":true,"etki":{"gelisim":1.6},"oyuncu":[]},{"ad":"Gönüllü arama kurtarma eğitimi","aciklama":"Oyuncuların kıdem kazanımı 7 gün %12 artar.","maliyet":4,"il_gerekli":false,"etki":{"memnuniyet":0.15},"oyuncu":[{"tur":"kidem_x","deger":12}]},{"ad":"Acil barınma kapasitesi","aciklama":"Ülke genelinde afet sonrası sosyal hizmetler iyileştirilir.","maliyet":5,"il_gerekli":false,"etki":{"memnuniyet":0.35},"oyuncu":[]}]'::jsonb,'[{"ad":"Afet hazırlık tatbikatı","aciklama":"Seçilen ilde gönüllüler afet tatbikatına katılır.","il_gerekli":true,"etki":{"il_memnuniyet":1,"gelisim":0.3},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Afet yönetimi koordinasyon toplantısı","aciklama":"Ülke genelinde gönüllü ve kurum temsilcileri görüşür.","il_gerekli":false,"etki":{"memnuniyet":0.2},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('bilim','Bilim, Teknoloji ve Uzay', '[{"ad":"Uzay ve teknoloji laboratuvarı","aciklama":"Seçilen ilde teknoloji araştırma laboratuvarı kurulur.","maliyet":6,"il_gerekli":true,"etki":{"gelisim":2,"buyume":0.03},"oyuncu":[]},{"ad":"Yapay zekâ araştırma fonu","aciklama":"Kamu araştırma harcamaları ülke büyümesini artırır.","maliyet":5,"il_gerekli":false,"etki":{"buyume":0.08},"oyuncu":[]},{"ad":"Bilim bursları programı","aciklama":"Oyuncuların 7 gün kıdem kazanımı %15 artar.","maliyet":4,"il_gerekli":false,"etki":{"memnuniyet":0.1},"oyuncu":[{"tur":"kidem_x","deger":15}]},{"ad":"Teknoloji kuluçka merkezi","aciklama":"Seçilen ilde girişim altyapısı kurulur.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.6},"oyuncu":[]}]'::jsonb,'[{"ad":"Uzay ve teknoloji fuarı","aciklama":"Oyuncular bilim projelerini sergiler.","il_gerekli":true,"etki":{"il_memnuniyet":0.7,"gelisim":0.5},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Bilim politikası çalıştayı","aciklama":"Araştırma öncelikleri tartışılır.","il_gerekli":false,"etki":{"buyume":0.02,"memnuniyet":0.1},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('basin','Basın, Medya ve İletişim', '[{"ad":"Yerel basın altyapı desteği","aciklama":"Seçilen ilde medya üretim imkânları gelişir.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.2},"oyuncu":[]},{"ad":"Medya okuryazarlığı programı","aciklama":"Oyuncuların 7 gün kıdem kazanımı %10 artar.","maliyet":3,"il_gerekli":false,"etki":{"memnuniyet":0.2},"oyuncu":[{"tur":"kidem_x","deger":10}]},{"ad":"Kamusal iletişim altyapısı","aciklama":"Seçilen ilde iletişim hizmetleri güçlendirilir.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.5},"oyuncu":[]},{"ad":"Bilgi edinme hizmetleri","aciklama":"Ülke genelinde kamu bilgilendirmesi geliştirilir.","maliyet":3,"il_gerekli":false,"etki":{"memnuniyet":0.35},"oyuncu":[]}]'::jsonb,'[{"ad":"Basın özgürlüğü forumu","aciklama":"Gazete ve kanal yöneticileri görüşlerini paylaşır.","il_gerekli":false,"etki":{"memnuniyet":0.2},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Yerel medya çalıştayı","aciklama":"Seçilen ilde gazeteci ve oyuncular buluşur.","il_gerekli":true,"etki":{"il_memnuniyet":0.8},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('din','Din İşleri', '[{"ad":"İnanç mirası restorasyonu","aciklama":"Seçilen ilde tarihi inanç mekânları korunur.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.3},"oyuncu":[]},{"ad":"Toplumsal dayanışma merkezi","aciklama":"Seçilen ilde kapsayıcı sosyal destek hizmeti gelişir.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.3,"memnuniyet":0.15},"oyuncu":[]},{"ad":"Manevi danışmanlık erişimi","aciklama":"Ülke genelinde gönüllü danışmanlık erişimi genişler.","maliyet":3,"il_gerekli":false,"etki":{"memnuniyet":0.3},"oyuncu":[]},{"ad":"Kültürel miras eğitimleri","aciklama":"Oyuncuların 7 gün kıdem kazanımı %8 artar.","maliyet":3,"il_gerekli":false,"etki":{"memnuniyet":0.15},"oyuncu":[{"tur":"kidem_x","deger":8}]}]'::jsonb,'[{"ad":"İnanç ve kültür diyaloğu","aciklama":"Farklı topluluklar karşılıklı anlayış için buluşur.","il_gerekli":false,"etki":{"memnuniyet":0.3},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Kültürel miras gezisi","aciklama":"Seçilen ilde tarihi miras buluşması yapılır.","il_gerekli":true,"etki":{"il_memnuniyet":0.7,"gelisim":0.3},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
INSERT INTO oyun.bakanlik_sablonlar(alan,ad,icraatlar,etkinlikler) VALUES('genel','Genel Kamu Hizmetleri', '[{"ad":"Yerel hizmet merkezi","aciklama":"Seçilen ilde bakanlığın yerel hizmet ofisi kurulur.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.2},"oyuncu":[]},{"ad":"Kamu erişimi iyileştirmesi","aciklama":"Seçilen ilde hizmet altyapısı güçlendirilir.","maliyet":4,"il_gerekli":true,"etki":{"gelisim":1.4},"oyuncu":[]},{"ad":"Mesleki eğitim programı","aciklama":"Oyuncuların kıdem kazanımı 7 gün %8 artar.","maliyet":3,"il_gerekli":false,"etki":{"memnuniyet":0.1},"oyuncu":[{"tur":"kidem_x","deger":8}]},{"ad":"Hizmet kalitesi programı","aciklama":"Ülke genelinde hizmet memnuniyeti yükselir.","maliyet":3,"il_gerekli":false,"etki":{"memnuniyet":0.25},"oyuncu":[]}]'::jsonb,'[{"ad":"Halkla hizmet toplantısı","aciklama":"Oyuncular hizmet önerilerini iletir.","il_gerekli":true,"etki":{"il_memnuniyet":0.7},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72},{"ad":"Hizmet koordinasyon forumu","aciklama":"Kamu hizmetleri üzerine çalıştay yapılır.","il_gerekli":false,"etki":{"memnuniyet":0.2},"maliyet":0.002,"sure_saat":24,"bekleme_saat":72}]'::jsonb) ON CONFLICT(alan) DO UPDATE SET ad=excluded.ad,icraatlar=excluded.icraatlar,etkinlikler=excluded.etkinlikler;
